CREATE TABLE IF NOT EXISTS player_modes (player_id TEXT NOT NULL REFERENCES players(id), mode TEXT NOT NULL CHECK (mode IN ('referencia', 'palavra')), games INTEGER NOT NULL DEFAULT 0 CHECK (games >= 0), wins INTEGER NOT NULL DEFAULT 0 CHECK (wins >= 0), current_streak INTEGER NOT NULL DEFAULT 0 CHECK (current_streak >= 0), max_streak INTEGER NOT NULL DEFAULT 0 CHECK (max_streak >= 0), last_played_day TEXT, PRIMARY KEY (player_id, mode));
CREATE INDEX IF NOT EXISTS player_modes_active ON player_modes(mode, last_played_day, player_id);
INSERT OR IGNORE INTO player_modes (player_id, mode, games, wins, current_streak, max_streak, last_played_day) SELECT id, 'referencia', COALESCE(json_extract(baseline, '$.referencia.games'), 0), COALESCE(json_extract(baseline, '$.referencia.wins'), 0), COALESCE(json_extract(baseline, '$.referencia.winStreak'), 0), COALESCE(json_extract(baseline, '$.referencia.maxStreak'), 0), COALESCE(json_extract(baseline, '$.referencia.lastPlayedDay'), json_extract(baseline, '$.referencia.lastWinDay')) FROM players;
INSERT OR IGNORE INTO player_modes (player_id, mode, games, wins, current_streak, max_streak, last_played_day) SELECT id, 'palavra', COALESCE(json_extract(baseline, '$.palavra.games'), 0), COALESCE(json_extract(baseline, '$.palavra.wins'), 0), COALESCE(json_extract(baseline, '$.palavra.winStreak'), 0), COALESCE(json_extract(baseline, '$.palavra.maxStreak'), 0), COALESCE(json_extract(baseline, '$.palavra.lastPlayedDay'), json_extract(baseline, '$.palavra.lastWinDay')) FROM players;
WITH base AS (SELECT pm.player_id, pm.mode, COALESCE(json_extract(p.baseline, '$.' || pm.mode || '.games'), 0) AS games, COALESCE(json_extract(p.baseline, '$.' || pm.mode || '.wins'), 0) AS wins, COALESCE(json_extract(p.baseline, '$.' || pm.mode || '.winStreak'), 0) AS current_streak, COALESCE(json_extract(p.baseline, '$.' || pm.mode || '.maxStreak'), 0) AS max_streak, COALESCE(json_extract(p.baseline, '$.' || pm.mode || '.lastPlayedDay'), json_extract(p.baseline, '$.' || pm.mode || '.lastWinDay')) AS last_played_day FROM player_modes pm JOIN players p ON p.id = pm.player_id), ordered AS (SELECT r.player_id, r.mode, r.day, r.won, ROW_NUMBER() OVER (PARTITION BY r.player_id, r.mode ORDER BY r.day) AS sequence_number, LAG(r.day) OVER (PARTITION BY r.player_id, r.mode ORDER BY r.day) AS previous_day, LAG(r.won) OVER (PARTITION BY r.player_id, r.mode ORDER BY r.day) AS previous_won FROM results r), marked AS (SELECT o.*, SUM(CASE WHEN o.won = 0 THEN 1 WHEN o.sequence_number = 1 AND b.current_streak > 0 AND b.last_played_day = date(o.day, '-1 day') THEN 0 WHEN o.previous_won = 1 AND o.previous_day = date(o.day, '-1 day') THEN 0 ELSE 1 END) OVER (PARTITION BY o.player_id, o.mode ORDER BY o.day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS streak_group FROM ordered o JOIN base b ON b.player_id = o.player_id AND b.mode = o.mode), runs AS (SELECT player_id, mode, streak_group, COUNT(*) AS streak_length FROM marked WHERE won = 1 GROUP BY player_id, mode, streak_group), ranked AS (SELECT player_id, mode, won, streak_group, ROW_NUMBER() OVER (PARTITION BY player_id, mode ORDER BY day DESC) AS reverse_number FROM marked), latest AS (SELECT player_id, mode, won, streak_group FROM ranked WHERE reverse_number = 1), totals AS (SELECT player_id, mode, COUNT(*) AS added_games, SUM(won) AS added_wins, MAX(day) AS last_day FROM ordered GROUP BY player_id, mode), progress AS (SELECT r.player_id, r.mode, MAX(r.streak_length + CASE WHEN r.streak_group = 0 THEN b.current_streak ELSE 0 END) AS max_streak, MAX(CASE WHEN r.streak_group = l.streak_group THEN r.streak_length + CASE WHEN r.streak_group = 0 THEN b.current_streak ELSE 0 END ELSE 0 END) AS current_streak FROM runs r JOIN base b ON b.player_id = r.player_id AND b.mode = r.mode JOIN latest l ON l.player_id = r.player_id AND l.mode = r.mode GROUP BY r.player_id, r.mode), combined AS (SELECT b.player_id, b.mode, b.games + COALESCE(t.added_games, 0) AS games, b.wins + COALESCE(t.added_wins, 0) AS wins, CASE WHEN l.won = 1 THEN COALESCE(p.current_streak, 0) ELSE 0 END AS current_streak, MAX(b.max_streak, COALESCE(p.max_streak, 0)) AS max_streak, MAX(COALESCE(b.last_played_day, ''), COALESCE(t.last_day, '')) AS last_played_day FROM base b LEFT JOIN totals t ON t.player_id = b.player_id AND t.mode = b.mode LEFT JOIN latest l ON l.player_id = b.player_id AND l.mode = b.mode LEFT JOIN progress p ON p.player_id = b.player_id AND p.mode = b.mode) UPDATE player_modes SET games = (SELECT games FROM combined WHERE combined.player_id = player_modes.player_id AND combined.mode = player_modes.mode), wins = (SELECT wins FROM combined WHERE combined.player_id = player_modes.player_id AND combined.mode = player_modes.mode), current_streak = (SELECT current_streak FROM combined WHERE combined.player_id = player_modes.player_id AND combined.mode = player_modes.mode), max_streak = (SELECT max_streak FROM combined WHERE combined.player_id = player_modes.player_id AND combined.mode = player_modes.mode), last_played_day = NULLIF((SELECT last_played_day FROM combined WHERE combined.player_id = player_modes.player_id AND combined.mode = player_modes.mode), '');
UPDATE player_modes SET last_played_day = NULL, current_streak = 0 WHERE games = 0;
CREATE TRIGGER IF NOT EXISTS initialize_player_modes AFTER INSERT ON players BEGIN INSERT OR IGNORE INTO player_modes (player_id, mode, games, wins, current_streak, max_streak, last_played_day) VALUES (NEW.id, 'referencia', COALESCE(json_extract(NEW.baseline, '$.referencia.games'), 0), COALESCE(json_extract(NEW.baseline, '$.referencia.wins'), 0), COALESCE(json_extract(NEW.baseline, '$.referencia.winStreak'), 0), COALESCE(json_extract(NEW.baseline, '$.referencia.maxStreak'), 0), COALESCE(json_extract(NEW.baseline, '$.referencia.lastPlayedDay'), json_extract(NEW.baseline, '$.referencia.lastWinDay'))), (NEW.id, 'palavra', COALESCE(json_extract(NEW.baseline, '$.palavra.games'), 0), COALESCE(json_extract(NEW.baseline, '$.palavra.wins'), 0), COALESCE(json_extract(NEW.baseline, '$.palavra.winStreak'), 0), COALESCE(json_extract(NEW.baseline, '$.palavra.maxStreak'), 0), COALESCE(json_extract(NEW.baseline, '$.palavra.lastPlayedDay'), json_extract(NEW.baseline, '$.palavra.lastWinDay'))); END;
CREATE TRIGGER IF NOT EXISTS update_player_mode_after_result AFTER INSERT ON results BEGIN UPDATE player_modes SET games = games + 1, wins = wins + NEW.won, current_streak = CASE WHEN NEW.day <= COALESCE(last_played_day, '') THEN current_streak WHEN NEW.won = 0 THEN 0 WHEN last_played_day = date(NEW.day, '-1 day') THEN current_streak + 1 ELSE 1 END, max_streak = MAX(max_streak, CASE WHEN NEW.day <= COALESCE(last_played_day, '') THEN current_streak WHEN NEW.won = 0 THEN 0 WHEN last_played_day = date(NEW.day, '-1 day') THEN current_streak + 1 ELSE 1 END), last_played_day = MAX(COALESCE(last_played_day, ''), NEW.day) WHERE player_id = NEW.player_id AND mode = NEW.mode; END;
